import{_ as o,o as t,c as n,a6 as a}from"./chunks/framework.BBdhcoHf.js";const m=JSON.parse('{"title":"ADR-005: Transport ABI Package","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-transport-abi.md","filePath":"adr/005-transport-abi.md","lastUpdated":1771970963000}'),r={name:"adr/005-transport-abi.md"};function i(c,e,s,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/005-transport-abi.md for this page in Markdown format</div><h1 id="adr-005-transport-abi-package" tabindex="-1">ADR-005: Transport ABI Package <a class="header-anchor" href="#adr-005-transport-abi-package" aria-label="Permalink to “ADR-005: Transport ABI Package”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: Architecture</li><li><strong>Tags</strong>: architecture, transport</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The project architecture requires a <code>@sideband/transport</code> package as the ABI layer between protocol and concrete implementations. The initial architecture inadvertently mixed transport concerns into <code>@sideband/protocol</code> via a low-level callback-based <code>RawTransport</code> interface.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Created <code>@sideband/transport</code> as a dedicated, transport-agnostic ABI layer:</p><p><strong>Core interfaces:</strong></p><ul><li><code>Transport</code>: Entry point for <code>connect()</code> (client) and optional <code>listen()</code> (server)</li><li><code>TransportConnection</code>: Bidirectional channel with <code>send()</code>, <code>close()</code>, and <code>inbound: AsyncIterable&lt;Uint8Array&gt;</code></li><li><code>TransportEndpoint</code>: Branded string for connection targets (format is transport-specific)</li></ul><p><strong>Dependency rule:</strong></p><ul><li><code>@sideband/transport</code> depends only on <code>@sideband/protocol</code> (imports <code>ConnectionId</code>)</li><li>All concrete transports (<code>transport-ws</code>) depend on <code>@sideband/transport</code></li><li><code>@sideband/runtime</code> depends on <code>@sideband/transport</code>, not on concrete implementations</li></ul><p><strong>Key constraint:</strong> No I/O, codec, or environment-specific logic. Transport is purely an interface contract.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><ul><li><strong>Layered isolation</strong>: Concrete transports depend on the ABI, not vice versa; enables swappable implementations</li><li><strong>Testability</strong>: LoopbackTransport reference implementation serves as both documentation and test harness</li><li><strong>Async iterables</strong>: Inbound stream via <code>AsyncIterable&lt;Uint8Array&gt;</code> enables backpressure, composition, and natural error handling</li><li><strong>Stateless types</strong>: <code>TransportEndpoint</code> and <code>ConnectionId</code> are transport-agnostic, avoiding implicit coupling</li></ul><h2 id="specification-documents" tabindex="-1">Specification Documents <a class="header-anchor" href="#specification-documents" aria-label="Permalink to “Specification Documents”">​</a></h2><p>Normative behavioral semantics are defined in the transport specification:</p><ul><li><code>docs/protocols/transport/abi.md</code> — Extended connection lifecycle and semantics</li><li><code>docs/protocols/transport/errors.md</code> — Error taxonomy and classification</li><li><code>docs/protocols/transport/websocket.md</code> — WebSocket-specific rules</li><li><code>docs/protocols/transport/conformance.md</code> — Conformance test matrix</li></ul><h2 id="key-types" tabindex="-1">Key Types <a class="header-anchor" href="#key-types" aria-label="Permalink to “Key Types”">​</a></h2><p>The specification documents extend the core interfaces with additional types:</p><ul><li><strong>ConnectionState</strong> — Finite state machine: <code>connecting</code>, <code>open</code>, <code>closing</code>, <code>closed</code></li><li><strong>TransportError</strong> — Structured error with <code>kind: TransportErrorKind</code> for classification</li><li><strong>TransportErrorKind</strong> — Error classification (see <code>transport/errors.md</code> for full taxonomy)</li><li><strong>CloseInfo</strong> — Details about connection closure: <code>graceful</code>, <code>closeCode</code>, <code>reason</code>, <code>error</code></li><li><strong>CloseOptions</strong> — Options for graceful shutdown: <code>closeCode</code>, <code>reason</code></li><li><strong>ConnectOptions</strong> — Connection options: <code>timeoutMs</code>, <code>signal</code> (transport-specific specs may extend)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>This ADR establishes the interface contract and architectural boundaries</li><li>The specification documents provide normative behavioral semantics that implementations must follow</li><li>Conformance tests validate that concrete transports adhere to both the ABI and behavioral specs</li><li>Updates to connection lifecycle or error handling require spec changes, not ADR amendments</li></ul>',22)])])}const u=o(r,[["render",i]]);export{m as __pageData,u as default};
